package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;import net.minecraft.nbt.*;
/** Mounts the existing, real DVT block/BE. Its original GUI, feeds, owner and drone data stay in charge. */
public final class Pb01Dvt{
 public static boolean authorized(Dvt01BlockEntity d,net.minecraft.world.entity.player.Player p){if(d.pbRoot==null)return true;var b=bunker(d);return b!=null&&!b.removing&&b.health[12]>0&&b.allowed(p,true);}
 public static Vec3 offset(Dvt01BlockEntity d){if(d.pbRoot==null)return Vec3.ZERO;return Pb01Geometry.MODEL.anchor(d.pbRoot,d.pbFacing,"DVT_Mount_Anchor").subtract(new Vec3(d.getBlockPos().getX()+.5,d.getBlockPos().getY(),d.getBlockPos().getZ()+.5));}
 public static Pb01BlockEntity bunker(Dvt01BlockEntity d){return d.pbRoot!=null&&d.getLevel()!=null&&d.getLevel().hasChunkAt(d.pbRoot)&&d.getLevel().getBlockEntity(d.pbRoot)instanceof Pb01BlockEntity b&&b.id.equals(d.pbBunker)?b:null;}
 public static BlockPos position(Pb01BlockEntity b){return BlockPos.containing(Pb01Geometry.MODEL.anchor(b.getBlockPos(),b.facing(),"DVT_Mount_Anchor"));}
 public static boolean supported(Dvt01BlockEntity d){if(d.pbRoot==null)return false;if(!d.getLevel().hasChunkAt(d.pbRoot))return true;var b=bunker(d);return b!=null&&!b.removing&&b.health[12]>0;}
 public static VoxelShape shape(Dvt01BlockEntity d,VoxelShape original){if(d.pbRoot==null)return original;var v=offset(d);var result=original.move(v.x,v.y,v.z);var p=d.getBlockPos();var b=bunker(d);var g=Pb01Geometry.MODEL;for(int i=0;i<g.body.length;i++)if(Pb01Geometry.cell(d.pbRoot,d.pbFacing,g.body[i]).equals(p)){int part=g.variant(false,g.bodyBase[i],b==null?0:~b.mask());result=Shapes.or(result,g.shape(d.pbFacing,false,part,0));break;}return result;}
 public static boolean install(Pb01BlockEntity b,ServerPlayer p,InteractionHand hand){if(!b.allowed(p,true)||b.health[12]<=0||!p.getItemInHand(hand).is(AddonItems.DVT01.get()))return false;var l=p.serverLevel();var at=position(b);if(!l.hasChunkAt(at)||!l.mayInteract(p,at)||p.getEyePosition().distanceToSqr(Pb01Geometry.MODEL.anchor(b.getBlockPos(),b.facing(),"DVT_Mount_Anchor"))>36)return false;var old=l.getBlockState(at);if(!(old.getBlock()instanceof Pb01Block)||!Pb01Block.root(at,old).equals(b.getBlockPos()))return false;var event=new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(l,at,old,p);boolean checking=Pb01Events.CHECKING.get();Pb01Events.CHECKING.set(true);try{if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event).isCanceled())return false;}finally{Pb01Events.CHECKING.set(checking);}var snapshot=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,at);boolean prior=Pb01Block.MUTATING.get();Pb01Block.MUTATING.set(true);try{if(!l.setBlock(at,AddonBlocks.DVT01.get().defaultBlockState().setValue(Dvt01Block.FACING,b.facing()),2))return false;var d=(Dvt01BlockEntity)l.getBlockEntity(at);if(d==null){snapshot.restore(3);return false;}var n=DefenseItem.data(p.getItemInHand(hand)).getCompound("PbTerminalState");if(!n.isEmpty())d.loadWithComponents(n,l.registryAccess());if(d.owner==null)d.owner=p.getUUID();d.pbRoot=b.getBlockPos();d.pbBunker=b.id;d.pbFacing=b.facing();d.pbItem=p.getItemInHand(hand).copy();d.pbItem.setCount(1);var placed=new net.neoforged.neoforge.event.level.BlockEvent.EntityPlaceEvent(snapshot,l.getBlockState(at.below()),p);if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(placed).isCanceled()){snapshot.restore(3);return false;}if(!p.isCreative())p.getItemInHand(hand).shrink(1);d.changed();l.updateNeighborsAt(at,AddonBlocks.DVT01.get());b.changed();return true;}finally{Pb01Block.MUTATING.set(prior);}}
 public static ItemStack stack(Dvt01BlockEntity d){var s=d.pbItem.isEmpty()?new ItemStack(AddonItems.DVT01.get()):d.pbItem.copy();s.setCount(1);var n=d.saveWithoutMetadata(d.getLevel().registryAccess());n.remove("PbItem");n.remove("PbRoot");n.remove("PbBunker");n.remove("PbFacing");var data=DefenseItem.data(s);data.put("PbTerminalState",n);DefenseItem.data(s,data);return s;}
 public static boolean detach(Pb01BlockEntity b,ServerPlayer p,boolean drop){var l=b.getLevel();var at=position(b);if(!l.hasChunkAt(at)||!(l.getBlockEntity(at)instanceof Dvt01BlockEntity d)||!b.id.equals(d.pbBunker))return false;if(p!=null&&!b.removing&&(!b.allowed(p,true)||!Pb01Events.permitBreak(p,at)))return false;dropAndRemove(d,p,drop);return true;}
 public static void dropAndRemove(Dvt01BlockEntity d,ServerPlayer p,boolean drop){if(!(d.getLevel()instanceof ServerLevel l))return;var at=d.getBlockPos();var root=d.pbRoot;var id=d.pbBunker;var item=stack(d);boolean old=Pb01Block.MUTATING.get();Pb01Block.MUTATING.set(true);try{l.removeBlock(at,false);}finally{Pb01Block.MUTATING.set(old);}if(drop&&(p==null||!p.isCreative())){if(p!=null)net.neoforged.neoforge.items.ItemHandlerHelper.giveItemToPlayer(p,item);else net.minecraft.world.Containers.dropItemStack(l,at.getX()+.5,at.getY()+.5,at.getZ()+.5,item);}restore(l,at,root,id);}
 public static void restore(Level l,BlockPos at,BlockPos root,java.util.UUID id){if(!(l instanceof ServerLevel)||root==null||!l.hasChunkAt(root)||!(l.getBlockEntity(root)instanceof Pb01BlockEntity b)||!b.id.equals(id)||b.removing||!l.getBlockState(at).isAir())return;var g=Pb01Geometry.MODEL;for(int i=0;i<g.body.length;i++)if(Pb01Geometry.cell(root,b.facing(),g.body[i]).equals(at)){int v=g.variant(false,g.bodyBase[i],~b.mask());if(g.variant(false,v).mask()!=0){boolean old=Pb01Block.MUTATING.get();Pb01Block.MUTATING.set(true);try{l.setBlock(at,Pb01Block.part(AddonBlocks.PB01.get().defaultBlockState().setValue(Pb01Block.FACING,b.facing()),v).setValue(Pb01Block.LIT,false),3);}finally{Pb01Block.MUTATING.set(old);}}return;}}
 public static void removed(Level l,BlockPos at,BlockEntity be){if(Pb01Block.MUTATING.get()||!(be instanceof Dvt01BlockEntity d)||d.pbRoot==null||!(l instanceof ServerLevel sl))return;var root=d.pbRoot;var id=d.pbBunker;sl.getServer().tell(new net.minecraft.server.TickTask(sl.getServer().getTickCount()+1,()->restore(l,at,root,id)));}
}
